var cascadingSlotGameResult=function(){var t=document.querySelector("#result-container"),i=document.querySelector("template"),n=0;return{onInputNickname:function(n){n.preventDefault();n.currentTarget.value!==""&&$(".error").addClass("hidden")},addTumble:function(){var r=i.content.cloneNode(!0);r.querySelector("span").textContent=n===0?"Base Spin":"Tumbling "+n;t.appendChild(r);n++},generateRandom:function(n,t,i){let r;while(!r){const u=Math.floor(Math.random()*(t-n+1))+n;i.indexOf(u)===-1&&(r=u)}return r},shuffle:function(n){let t=n.length,i;while(t!==0)i=Math.floor(Math.random()*t),t--,[n[t],n[i]]=[n[i],n[t]];return n},importTemplateResults:function(n){var i,t,u,r;if(n.preventDefault(),i=$("#Nickname").val(),i===undefined||i===""){$(".error").removeClass("hidden");return}for(t=new FormData,u=document.getElementById("file").files,r=0;r<u.length;r++)t.append("file",u[r]),t.append("gameConfigName",$("#GameName").val()),t.append("nickame",i);$.ajax({type:"POST",url:"ImportTemplateResults",data:t,processData:!1,contentType:!1,dataType:"html",success:function(n){$("#set-result").html(n)},error:function(n){console.log(n)}})},submit:function(n){var t,i,r,u;try{if(n.preventDefault(),t=[],i=this,$(".result-temp").each(function(){var n=[],f=0,r=[],u;for($(this).find('select[id^="Item"]').map(function(){var u=parseInt($(this).attr("data-no")),t=parseInt($(this).val()),i;for(f+=t,t>0&&r.push(u),i=t;i>0;i--)n.push(u)}),u=30-f;u>0;u--)n.push(i.generateRandom(0,10,r));console.log(r);t.push({Name:$(this).find(".attempt").text(),Value:i.shuffle(n).join(",")});console.log(t);console.log(i.shuffle(n))}),r=$("#Nickname").val(),r===undefined||r===""){$(".error").removeClass("hidden");return}u={roundName:r,rawResults:t,gameConfigName:$("#GameName").val()};$.ajax({type:"POST",url:"SetCascadingSlotResult",data:u,dataType:"html",success:function(n){$("#set-result").html(n)}})}catch(f){console.log(f)}}}}();$(document).ready(function(){cascadingSlotGameResult.addTumble()});